package com.fertiplus.inventory;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class InventoryReservationService { private final StockRepository stocks; private final ReservationRepository reservations; public InventoryReservationService(StockRepository stocks,ReservationRepository reservations){this.stocks=stocks;this.reservations=reservations;} @Transactional public ReservationEntity reserve(String orderId,Long productId,int quantity){ReservationEntity existing=reservations.findById(orderId).orElse(null);if(existing!=null)return existing;String status=(quantity>0 && stocks.reserve(productId,quantity)==1)?"RESERVED":"REJECTED";return reservations.saveAndFlush(new ReservationEntity(orderId,productId,quantity,status));} @Transactional public void release(String orderId){ReservationEntity r=reservations.findById(orderId).orElse(null);if(r==null||!"RESERVED".equals(r.status))return;stocks.release(r.productId,r.quantity);r.status="RELEASED";reservations.save(r);} }
